using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway gateway;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = provider.BaseAddress };
        gateway = new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"abc","status":"approved","risk":{"score":3}}""");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_not_an_error()
    {
        provider.Respond(402, """{"error":"insufficient_funds"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_with_an_empty_body_is_still_a_decline()
    {
        provider.Respond(402, "");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors_instead_of_looking_like_declines(int status)
    {
        provider.Respond(status, """{"error":"nope"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None));

        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_status_the_gateway_does_not_know_is_not_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending_review"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""null""")]
    public async Task An_answer_without_a_status_is_not_treated_as_approved(string body)
    {
        provider.Respond(200, body);

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_fails_loudly()
    {
        provider.Respond(200, "<html>gateway error</html>");

        await Assert.ThrowsAsync<JsonException>(
            () => gateway.AuthorizeAsync("ORD-1", new Money(1, "EUR"), CancellationToken.None));
    }

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<ReceivedRequest> requests = [];
        private volatile int status = 200;
        private volatile string body = "";

        public FakeProvider()
        {
            // Retry on a few random ports in case one is taken.
            for (var attempt = 0; ; attempt++)
            {
                var port = Random.Shared.Next(20000, 60000);
                var prefix = $"http://127.0.0.1:{port}/";
                try
                {
                    listener.Prefixes.Add(prefix);
                    listener.Start();
                    BaseAddress = new Uri(prefix);
                    break;
                }
                catch (HttpListenerException) when (attempt < 10)
                {
                    listener.Prefixes.Clear();
                }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; }

        public IReadOnlyList<ReceivedRequest> Requests
        {
            get { lock (requests) return requests.ToArray(); }
        }

        public void Respond(int statusCode, string responseBody)
        {
            status = statusCode;
            body = responseBody;
        }

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var requestBody = await reader.ReadToEndAsync();
                lock (requests)
                {
                    requests.Add(new ReceivedRequest(
                        context.Request.HttpMethod,
                        context.Request.Url!.AbsolutePath,
                        context.Request.ContentType,
                        requestBody));
                }

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
